sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') return;

    var ga = new GlideAjax('ScheduleDateCheck');
    ga.addParam('sysparm_name', 'checkMaxVacancies');
    ga.addParam('sysparm_max_vacancies', newValue);

    ga.getXMLAnswer(function(response) {
        if (response === 'invalid') {
			g_form.clearValue('max_vacancies');
            g_form.showFieldMsg('max_vacancies', 'Max Vacancies cannot be 0', 'error');
			return;
        } 
		g_form.setValue('max_vacancies', value);
		g_form.hideFieldMsg('max_vacancies', true);
    });
}
